-- Org effect signature: generated business projection IDs (not named in the normalized change) are compared semantically, not by random UUID.
-- Preflight: md5(pg_get_functiondef('private.org_effect_signature'::regproc)) = a5b4eead675d66f64472b7553fe48780, owner postgres, acl {postgres=X/postgres}.
CREATE OR REPLACE FUNCTION private.org_effect_signature(c jsonb, changes_ jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$ SELECT jsonb_build_object('position_slots',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'id'),'[]') FROM (SELECT jsonb_build_object('id',s->>'id','title_id',s->>'title_id','unit_id',s->>'unit_id','role_id',s->>'role_id','name',s->>'name','active',s->>'active') x FROM jsonb_array_elements(coalesce(c->'position_slots','[]')) s) q),'units',c->'units','titles',c->'titles','assignments',(SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') FROM (SELECT jsonb_build_object('id',CASE WHEN position(('"'||(m->>'id')||'"') IN changes_::text)>0 THEN m->>'id' END,'slot_id',m->>'slot_id','unit_id',m->>'unit_id','title_id',m->>'title_id','user_id',m->>'user_id','category',m->>'category','starts_at',m->>'starts_at','ends_at',m->>'ends_at','status',m->>'status') x FROM jsonb_array_elements(c->'memberships')m)s),'role_links',(SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') FROM (SELECT jsonb_build_object('title_source',l->>'title_source','title_id',l->>'title_id','role_id',l->>'role_id','is_primary',l->>'is_primary','scope_kind',l->>'scope_kind','enabled_permissions',l->>'enabled_permissions','permission_signature',l->>'permission_signature') x FROM jsonb_array_elements(coalesce(c->'role_links','[]')) l)s),'permissions',jsonb_build_object('defaults',c->'defaults','bundles',c->'bundles','grants',c->'grants','bindings',c->'bindings')) $function$;
REVOKE ALL ON FUNCTION private.org_effect_signature(jsonb,jsonb) FROM PUBLIC;
